window.__votdWeek && window.__votdWeek({"week":"2028-05-08","reading":"Mosiah 11–17","days":[{"d":"2028-05-08","ref":"Mosiah 11:22","b":"Mosiah","c":11,"v":22,"he":"וְהָיָה כִּי יֵדְעוּ כִּי־אֲנִי יְהוָה אֱלֹהֵיהֶם אֵל קַנָּא פֹּקֵד עֲוֹן עַמִּי׃","en":"And it shall come to pass that they shall know that I am the Lord their God, and am a jealous God, visiting the iniquities of my people."},{"d":"2028-05-09","ref":"Mosiah 11:24","b":"Mosiah","c":11,"v":24,"he":"וְהָיָה כִּי יִזְעֲקוּ אֵלַי אֶתְאַפַּק מִשְּׁמֹעַ זַעֲקָתָם וְאֶתְּנֵם לְהִנָּגֵף לִפְנֵי אֹיְבֵיהֶם׃","en":"Yea, and it shall come to pass that when they shall cry unto me I will be slow to hear their cries; yea, and I will suffer them that they be smitten by their enemies."},{"d":"2028-05-10","ref":"Mosiah 12:6","b":"Mosiah","c":12,"v":6,"he":"וְהָיָה כִּי אַשְׁלִיךְ בָּרָד עֲלֵיהֶם וְהִכָּה אֹתָם וְגַם־יֻכּוּ בְּרוּחַ הַקָּדִים וְשֶׁרֶץ יְשַׁחֵת אֶת־אַרְצָם וְיֹאכַל אֶת־דְּגָנָם׃","en":"And it shall come to pass that I will send forth hail among them, and it shall smite them; and they shall also be smitten with the east wind; and insects shall pester their land also, and devour their grain."},{"d":"2028-05-11","ref":"Mosiah 13:19","b":"Mosiah","c":13,"v":19,"he":"כִּי שֵׁשֶׁת־יָמִים עָשָׂה יְהוָה אֶת־הַשָּׁמַיִם וְאֶת־הָאָרֶץ אֶת־הַיָּם וְאֶת־כׇּל־אֲשֶׁר־בָּם עַל־כֵּן בֵּרַךְ יְהוָה אֶת־יוֹם הַשַּׁבָּת וַיְקַדְּשֵׁהוּ׃","en":"For in six days the Lord made heaven and earth, and the sea, and all that in them is; wherefore the Lord blessed the sabbath day, and hallowed it."},{"d":"2028-05-12","ref":"Mosiah 13:29","b":"Mosiah","c":13,"v":29,"he":"וְעַתָּה אֹמֵר אֲנִי לָכֶם כִּי נָכוֹן הָיָה לָתֵת תּוֹרָה לִבְנֵי יִשְׂרָאֵל אַף תּוֹרָה חֲזָקָה מְאֹד כִּי עַם־קְשֵׁה־עֹרֶף הֵמָּה מְמַהֲרִים לַעֲשׂוֹת רָעָה וּמְאַחֲרִים לִזְכֹּר אֶת־יְהוָה אֱלֹהֵיהֶם׃","en":"And now I say unto you that it was expedient that there should be a law given to the children of Israel, yea, even a very strict law; for they were a stiffnecked people, quick to do iniquity, and slow to remember the Lord their God;"},{"d":"2028-05-13","ref":"Mosiah 14:7","b":"Mosiah","c":14,"v":7,"he":"נִגַּשׂ וְהוּא נַעֲנֶה וְלֹא יִפְתַּח־פִּיו כַּשֶּׂה לַטֶּבַח יוּבָל וּכְרָחֵל לִפְנֵי גֹזְזֶיהָ נֶאֱלָמָה כֵּן לֹא פָתַח אֶת־פִּיהוּ׃","en":"He was oppressed, and he was afflicted, yet he opened not his mouth; he is brought as a lamb to the slaughter, and as a sheep before her shearers is dumb so he opened not his mouth."},{"d":"2028-05-14","ref":"Mosiah 16:2","b":"Mosiah","c":16,"v":2,"he":"וְאָז יֻשְׁלְכוּ הָרְשָׁעִים וְיֵשׁ לָהֶם לְהֵילִיל וְלִבְכּוֹת וּלְקוֹנֵן וְלַחֲרֹק שֵׁן וְזֹאת כִּי־לֹא שָׁמְעוּ לְקוֹל יְהוָה עַל־כֵּן לֹא יִגְאָלֵם יְהוָה׃","en":"And then shall the wicked be cast out, and they shall have cause to howl, and weep, and wail, and gnash their teeth; and this because they would not hearken unto the voice of the Lord; therefore the Lord redeemeth them not."}]});
